"use strict";(globalThis.webpackChunkgain=globalThis.webpackChunkgain||[]).push([[9967],{42085(e){e.exports=JSON.parse('{"tag":{"label":"ai-intelligence","permalink":"/playbooks/tags/ai-intelligence","allTagsPath":"/playbooks/tags","count":30,"items":[{"id":"agents/overview","title":"Agents Playbooks","description":"Hub for Agents playbooks: intent routing, orchestration (session, memory, autonomy), and tool manifests.","permalink":"/playbooks/agents"},{"id":"agents/orchestration/autonomy-shape","title":"Autonomy Shape","description":"Run Pattern 0-3 from the pinned route: single inference, autonomous loop, fixed workflow, or guided hybrid inside Plane \u2461.","permalink":"/playbooks/agents/orchestration/autonomy-shape"},{"id":"llm/canary-promotion","title":"Canary Promotion","description":"Eval-gated model swap and rollback at the LLM gateway: change records, traffic split, and when canary becomes stable.","permalink":"/playbooks/llm/canary-promotion"},{"id":"llm/capability-matrix","title":"Capability Matrix","description":"Versioned registry of approved model endpoints per profile, task, data class, and region: the Plane \u2462 source of truth.","permalink":"/playbooks/llm/capability-matrix"},{"id":"evaluation/overview","title":"Eval Engineering Playbooks","description":"Hub for eval engineering playbooks \u2014 golden datasets, synthetic generation, online scoring, human review, LLM-as-judge, and per-plane recipes.","permalink":"/playbooks/evaluation"},{"id":"evaluation/planes/plane-input","title":"Eval Plane \u2460: Input","description":"How to evaluate the Input plane \u2014 parsing, intent, injection resistance, and PII handling before inference begins.","permalink":"/playbooks/evaluation/plane-input"},{"id":"evaluation/planes/plane-data","title":"Eval Plane \u2461: Data","description":"How to evaluate the Data plane \u2014 source freshness, lineage, access boundaries, and factual correctness of underlying knowledge.","permalink":"/playbooks/evaluation/plane-data"},{"id":"evaluation/planes/plane-context","title":"Eval Plane \u2462: Context","description":"How to evaluate the Context plane \u2014 retrieval precision, ranking, scope, packing, and abstention when evidence is thin.","permalink":"/playbooks/evaluation/plane-context"},{"id":"evaluation/planes/plane-reasoning","title":"Eval Plane \u2463: Reasoning","description":"How to evaluate the Reasoning plane \u2014 faithfulness to context, conclusion quality, tool selection, and multi-step logic.","permalink":"/playbooks/evaluation/plane-reasoning"},{"id":"evaluation/planes/plane-tool","title":"Eval Plane \u2464: Tool","description":"How to evaluate the Tool plane \u2014 selection, arguments, idempotency, error handling, and schema compliance for agent tool calls.","permalink":"/playbooks/evaluation/plane-tool"},{"id":"evaluation/planes/plane-memory","title":"Eval Plane \u2465: Memory","description":"How to evaluate the Memory plane \u2014 session scope, TTL, consistency, and cross-session leakage in agent and copilot systems.","permalink":"/playbooks/evaluation/plane-memory"},{"id":"evaluation/planes/plane-action","title":"Eval Plane \u2466: Action","description":"How to evaluate the Action plane \u2014 policy enforcement, authorization, side effects, and auditability before irreversible operations execute.","permalink":"/playbooks/evaluation/plane-action"},{"id":"evaluation/planes/plane-outcome","title":"Eval Plane \u2467: Outcome","description":"How to evaluate the Outcome plane \u2014 end-user task success, clarity, usefulness, and trust in the final delivered response.","permalink":"/playbooks/evaluation/plane-outcome"},{"id":"evaluation/further-reading","title":"Further Reading","description":"Curated third-party articles, guides, and tool docs on LLM and agent evaluation \u2014 mapped to the Eval Framework Blueprint series.","permalink":"/playbooks/evaluation/further-reading"},{"id":"llm/gateway-task-routing","title":"Gateway Task Routing","description":"Per-call filter, score, and pick (or abstain) at the LLM gateway: task type, failover, cost caps, and residency.","permalink":"/playbooks/llm/gateway-task-routing"},{"id":"evaluation/golden-datasets","title":"Golden Datasets: Building Eval Data That Predicts Production","description":"How to design, version, and maintain golden datasets for plane-aware evaluation \u2014 representative tasks, edge cases, adversarial cases, and production replays.","permalink":"/playbooks/evaluation/golden-datasets"},{"id":"evaluation/human-review","title":"Human Review: Manual Eval That Calibrates the System","description":"Playbooks for human evaluation in production AI \u2014 sampling strategy, rubrics, adjudication, and how manual scores anchor automated and LLM-as-judge gates.","permalink":"/playbooks/evaluation/human-review"},{"id":"agents/orchestration/inference-handoff","title":"Inference Handoff","description":"Every plan or synthesize call goes through Plane \u2462, then validate proposals against the manifest and gate side effects at the PEP.","permalink":"/playbooks/agents/orchestration/inference-handoff"},{"id":"agents/intent-router/overview","title":"Intent Router Playbooks","description":"Hub for intent routing playbooks: route contract reference, route table lifecycle, layered classification, agentic app wiring, and routing eval CI.","permalink":"/playbooks/agents/intent-router"},{"id":"agents/intent-router/layered-classifier","title":"Layered Classifier","description":"Implement intent classification: eligible routes, rules (channel and event), classifier, LLM fallback, safety veto, and outcomes before the agent loop.","permalink":"/playbooks/agents/intent-router/layered-classifier"},{"id":"evaluation/llm-as-judge","title":"LLM-as-Judge: Scaled Eval With Calibration","description":"How to deploy LLM-as-judge for plane-aware evaluation \u2014 rubric design, judge selection, bias controls, and calibration against human ground truth.","permalink":"/playbooks/evaluation/llm-as-judge"},{"id":"llm/overview","title":"Model Routing Playbooks","description":"Hub for Plane \u2462 model routing playbooks: capability matrix, gateway task routing, and eval-gated canary promotion at the LLM gateway.","permalink":"/playbooks/llm"},{"id":"evaluation/online-dynamic","title":"Online & Dynamic Eval: Scoring Production After Ship","description":"How to run online evaluation on live traffic \u2014 sampling, shadow scoring, canary eval, drift detection, and promoting production signals back into golden datasets.","permalink":"/playbooks/evaluation/online-dynamic"},{"id":"agents/orchestration/overview","title":"Orchestration Playbooks","description":"Hub for Plane \u2461 orchestration playbooks: session custody, memory, autonomy shape, and inference handoff after the intent router decides and the app pins the run.","permalink":"/playbooks/agents/orchestration"},{"id":"agents/intent-router/route-contract-reference","title":"Route Contract Reference","description":"Field dictionary for route table rows: route, activation target (which agentic app to start), manifest, policy, retrieval, memory, workflow, and related artifact ids.","permalink":"/playbooks/agents/intent-router/route-contract-reference"},{"id":"agents/intent-router/route-table-lifecycle","title":"Route Table Lifecycle","description":"Where route contracts live, how to version and promote them, entitlement requirements per row, and rollback in regulated environments.","permalink":"/playbooks/agents/intent-router/route-table-lifecycle"},{"id":"agents/intent-router/routing-eval-ci","title":"Routing Eval CI","description":"Golden intent sets, release gates, adversarial coverage, and incident replay for Plane \u2460 routing \u2014 aligned with Eval Input plane.","permalink":"/playbooks/agents/intent-router/routing-eval-ci"},{"id":"agents/orchestration/session-custody","title":"Session Custody","description":"Two pins, durable run store, and when a checkpointer or Temporal is enough: loop bounds, credential stripping, restart by run_id.","permalink":"/playbooks/agents/orchestration/session-custody"},{"id":"evaluation/synthetic-generation","title":"Synthetic Eval Generation: Scaling Coverage Safely","description":"How to generate synthetic eval cases for edge and adversarial coverage \u2014 without polluting golden datasets or optimizing for the generator.","permalink":"/playbooks/evaluation/synthetic-generation"},{"id":"agents/intent-router/wire-agentic-app","title":"Wire Agentic App","description":"Decide-only router: freeze the route, async-start the app, skip the loop on clarify/abstain. UI and event ingress.","permalink":"/playbooks/agents/intent-router/wire-agentic-app"}],"unlisted":false}}')}}]);